def write(path_csv, path_md):
    with open(path_csv, "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=F); w.writeheader()
        for g in G: w.writerow(g)
    order = {"P0":0,"P1":1,"P2":2,"P3":3}; sev={"Critical":0,"High":1,"Medium":2,"Low":3}
    rows = sorted(G, key=lambda g:(order[g["priority"]], sev[g["severity"]], g["id"]))
    out = []
    for p in ("P0","P1","P2","P3"):
        out.append(f"\n## {p}\n")
        for g in [r for r in rows if r["priority"]==p]:
            out.append(f"### {g['id']} — {g['title']}\n")
            out.append(f"**Severity:** {g['severity']} · **Category:** {g['category']} · **Module:** {g['module']} · **Roles:** {g['roles']} · **Status:** {g['status']} · **Classification:** {g['classification']} · **Owner decision:** {g['owner_decision']}\n")
            for k,lab in (("expected_and_source","Expected (source)"),("actual_and_evidence","Actual (evidence)"),("impact","Impact"),("resolution","Resolution"),("alternatives","Alternatives"),("acceptance_criteria","Acceptance criteria"),("tests","Tests"),("depends_on","Depends on")):
                if g[k]: out.append(f"- **{lab}:** {g[k]}")
            out.append("")
    with open(path_md, "w", encoding="utf-8") as f: f.write("\n".join(out))
    print(len(G), "gaps;", {p: sum(1 for g in G if g['priority']==p) for p in order}, {s: sum(1 for g in G if g['severity']==s) for s in sev})

if __name__ == "__main__":
    write(sys.argv[1], sys.argv[2])
